import {rbLabTrace,parseRBKeys,parseRBOps} from './redblack-lab-engine.js';
import {rbCases,rbPresets,rbInsertCode,rbDeleteCode,rbReading} from './redblack-lab-content.js';
import {esc,rbTreeSVG,rbGuideSVG,rb234SVG} from './redblack-lab-view.js';
const $=s=>document.querySelector(s);
const save=(name,text,type)=>{const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
export function rbMemoryText(){return '# 红黑树插入与删除：记忆卡\n\n在线：https://stan-haochen.github.io/ads-knowledge-site/#btrees/redblack-lab\n\n插入：叔红推；叔黑先拉直，再换色旋祖。\n删除：兄红换，双黑推，近红转，远红收。\n\n'+Object.entries(rbCases).map(([id,c])=>`## ${id} ${c.name}\n条件：${c.test}\n动作：${c.action}\n原因：${c.why}\n下一步：${c.next}\n记忆：${c.memory}`).join('\n\n')+'\n\n## 插入伪代码\n```\n'+rbInsertCode.join('\n')+'\n```\n\n## 删除伪代码\n```\n'+rbDeleteCode.join('\n')+'\n```\n\n'+rbReading.replace(/<h[23]>(.*?)<\/h[23]>/g,'\n## $1\n').replace(/<li>/g,'\n- ').replace(/<a href="([^"]+)"[^>]*>(.*?)<\/a>/g,'[$2]($1)').replace(/<\/(?:p|details)>/g,'\n\n').replace(/<[^>]+>/g,'')}
function nodes(root){const a=[];function go(n){a.push(n);if(!n.nil){go(n.left);go(n.right)}}go(root);return a}
export function mountRedBlackLab(){
 let frames=[],pos=0,timer=null,presetId='delete-near',showNil=false,actual=false,quiz=false,revealed=false,feedback='',mirrorMode=false;
 document.title='红黑树：插入与删除的图解记忆 · ADS';$('#breadcrumb').textContent='第二课 / 红黑树插入与删除';document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.toggle('active',a.dataset.chapter==='btrees'));
 $('#main').innerHTML=`<article class="rb-page"><div class="eyebrow">CHAPTER 02 / RED–BLACK TREE</div><h1>插入看叔，删除看兄侄<span class="rb-subtitle">把红黑树修复记成一条有原因的决策链</span></h1><p class="intro">固定角色、对称规则、黑数守恒。先看一棵小树如何修好，再把案例连成通用判断方法。</p><div class="rb-memory"><div><small>INSERT / 红红冲突</small><b>叔红变色上推</b><span>叔黑：折线先拉直，直线换色旋祖</span></div><div><small>DELETE / 黑色亏欠</small><b>兄红换 · 双黑推 · 近红转 · 远红收</b><span>后三句的前提都是兄弟黑；远侄红可直接收尾</span></div></div><div class="rb-links"><button data-rb-jump="rb-animation">操作动画 ↓</button><button data-rb-jump="rb-guide">决策记忆图 ↓</button><button data-rb-jump="rb-explain">为什么正确 ↓</button><button id="rb-export-guide">下载一页记忆图 SVG</button><button id="rb-export-notes">下载图解讲义 Markdown</button><a href="#btrees/rb-compare">Top-down / Bottom-up 对比 ↗</a><a href="#btrees">返回第二课 ↗</a></div>
 <section id="rb-animation" class="rb-section"><h2>先看、再判、再动</h2><p>默认从“近红转出远红”开始。每个修复分成判定帧与执行帧，稳定编号追踪同一节点。绿色文字说明动作，橙色 +1 跟踪欠黑位置。</p><div class="rb-toolbar"><label class="rb-wide">教学案例<select id="rb-preset">${rbPresets.map(p=>`<option value="${p.id}" ${p.id===presetId?'selected':''}>${p.name}</option>`).join('')}</select></label><button id="rb-mirror">镜像重放 ↔</button><button id="rb-quiz" aria-pressed="false">开启预测模式</button></div><p id="rb-preset-why" class="rb-note"></p><details class="rb-custom"><summary>自定义初始树与操作序列</summary><div class="rb-toolbar"><label class="rb-wide">初始插入序列<input id="rb-initial" aria-label="红黑树初始序列"></label><label class="rb-wide">操作（i 插入 / d 删除 / f 查找）<input id="rb-ops" aria-label="红黑树操作序列"></label><button id="rb-run" class="primary">生成动画</button></div><p>初始树按标准红黑插入生成；每栏最多 24 项，键为 −999…999。重复插入和删除缺失键不改变树。</p></details><p id="rb-error" role="alert"></p><div class="rb-player"><button id="rb-first" aria-label="红黑树回到初始状态">↺</button><button id="rb-prev" aria-label="红黑树上一步">◀</button><button id="rb-play" class="primary">▶ 播放</button><button id="rb-next" aria-label="红黑树下一步">▶|</button><input id="rb-seek" type="range" min="0" value="0" aria-label="红黑树动画步骤"><label>速度<select id="rb-speed"><option value="1500">慢速</option><option value="1000" selected>标准</option><option value="500">快速</option></select></label></div><div class="rb-toolbar"><label class="rb-wide">关键步骤<select id="rb-checkpoint"></select></label><button id="rb-nil" aria-pressed="false">显示全部 NIL</button><button id="rb-size" aria-pressed="false">原始字号</button></div><div id="rb-stage"></div></section>
 <section id="rb-guide" class="rb-section"><h2>一页记忆图：七类规则，一条判断顺序</h2><p>点击 I1–I3 或 D1–D4 卡片，跳到对应动画的第一个判定。卡片写的是条件、动作和去向；左右镜像共用同一张卡。</p><div class="rb-scroll" id="rb-guide-visual">${rbGuideSVG()}</div><div class="rb-cards">${Object.entries(rbCases).map(([id,c])=>`<details><summary>${id} · ${c.name}</summary><p><b>条件：</b>${c.test}</p><p><b>动作：</b>${c.action}</p><p><b>为什么：</b>${c.why}</p><p><b>下一步：</b>${c.next}</p></details>`).join('')}</div></section>
 <section id="rb-explain" class="rb-section rb-reading">${rbReading}</section><div class="rb-links"><button data-rb-jump="rb-animation">回到动画 ↑</button><a href="#mindmap/btrees">课程地图 ↗</a></div></article>`;
 const stop=()=>{clearInterval(timer);timer=null;if($('#rb-play'))$('#rb-play').textContent='▶ 播放'};
 function bindGuide(){document.querySelectorAll('[data-rb-guide]').forEach(el=>{const go=()=>{const id=el.dataset.rbGuide,p=rbPresets.find(p=>p.target===id);loadPreset(p.id);pos=frames.findIndex(f=>f.phase==='decision'&&f.caseId===id);paint();$('#rb-animation').scrollIntoView({behavior:'smooth'})};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}})}
 function setPosition(i){stop();pos=i;revealed=false;feedback='';paint()}
 function paint(){const f=frames[pos],prev=frames[Math.max(0,pos-1)],hidden=quiz&&f.phase==='decision'&&!revealed,ins=f.caseId?.startsWith('I')||(!f.meta&&f.phase!=='remove'),caseInfo=rbCases[f.caseId],all=nodes(f.root),old=nodes(prev.root),name=id=>{const n=all.find(n=>n.id===id)||old.find(n=>n.id===id);return n?(n.nil?'NIL':String(n.key))+' · '+id:'已移除 '+id},black=[...new Set(f.paths.map(p=>p.black))],effective=[...new Set(f.paths.map(p=>p.effective))],isComplete=['start','begin','complete'].includes(f.phase),roleNames={X:ins?'当前节点':'欠黑 / 替代位置',P:'父亲',G:'祖父',U:'叔叔',S:'兄弟',N:'近侄',F:'远侄',Z:'删除目标',Y:'真正摘除'};
 const expanded=[...document.querySelectorAll('#rb-stage details[open]')].map(e=>e.id);const oldPositions=new Map([...document.querySelectorAll('#rb-current [data-rb-node]')].map(e=>[e.dataset.rbNode,{x:+e.dataset.x,y:+e.dataset.y,fill:e.querySelector('.rb-node-body')?.getAttribute('fill')}]));
 $('#rb-stage').innerHTML=`<div class="rb-situation"><span class="rb-step">STEP ${pos+1}/${frames.length} · 操作 ${f.operation||'准备'} ${f.side?'· 本步起始方位：'+(f.side==='L'?(ins?'父 P 在祖父左侧':'X 在父亲左侧'):(ins?'父 P 在祖父右侧':'X 在父亲右侧')):''}</span><h3>${hidden?'轮到你：下一步怎么修？':esc(f.title)}</h3><p>${hidden?'先认角色，再看颜色。选择下一条规则，或展开答案后继续。':esc(f.text)}</p>${hidden?`<div class="rb-answers">${(ins?['I1','I2','I3','I-root']:['D1','D2','D3','D4','D-absorb','D-root']).map(id=>`<button data-rb-answer="${id}">${id} · ${rbCases[id]?.name||(id==='I-root'?'根染黑':id==='D-root'?'根处终止':'红 X 吸收')}</button>`).join('')}<button id="rb-reveal">直接看答案</button></div>`:''}<p class="rb-feedback" role="status">${esc(feedback)}</p>${!hidden&&caseInfo?`<div class="rb-reason"><b>${caseInfo.memory}</b><p>为什么：${caseInfo.why}</p><p>下一步：${caseInfo.next}</p></div>`:''}</div>
 <div class="rb-status"><span>本次旋转 <b>${f.rotations}</b></span><span>实际路径黑数 <b>${black.join(' / ')}</b></span><span>补记 +1 后 <b>${effective.join(' / ')}</b></span><span>${f.debt?'欠黑位置 <b>'+esc(name(f.debt))+'</b>':'<b>无黑色亏欠</b>'}</span></div><p class="rb-caption">路径黑数包含根与终点 NIL。R/B 是实际颜色；+1 只是补计标记。${isComplete?'当前为合法操作边界。':'当前是修复中间状态，尚不要求实际颜色满足全部性质。'}</p>
 <div class="rb-pair ${actual?'rb-actual':''}"><figure><figcaption>上一步 <span>${esc(prev.title)}</span></figcaption><div class="rb-scroll">${rbTreeSVG(prev.root,{roles:prev.roles,debt:prev.debt,showNil,title:'上一步的红黑树'})}</div></figure><figure><figcaption>当前 <span>${hidden?'根据颜色判断下一步':esc(f.title)}</span></figcaption><div class="rb-scroll" id="rb-current">${rbTreeSVG(f.root,{roles:f.roles,debt:f.debt,showNil,title:'当前红黑树与角色'})}</div></figure></div>
 <div class="rb-role-list"><b>${esc(f.roleScope)}${f.roleScope.startsWith('下一轮')?' · 动作中的旧名称对应左图，右图用于下一次判断':''}</b>${Object.entries(f.roles).map(([r,id])=>`<span><b>${r}</b> ${roleNames[r]||r}：${esc(name(id))}</span>`).join('')||'<span>尚未进入修复轮，无需记角色。</span>'}</div>
 ${f.meta?`<div class="rb-identity">目标 <b>${f.meta.targetKey} / ${f.meta.targetId}</b> → 真正摘除 <b>${f.meta.physicalKey} / ${f.meta.physicalId}</b> → 原颜色 <b>${f.meta.removedColor==='R'?'红 R':'黑 B'}</b><br>${f.meta.targetId!==f.meta.physicalId?'采用复制'+f.meta.replacementMode+'键/载荷：目标对象保留其原颜色，'+f.meta.replacementMode+'对象被摘除。':'目标本身至多一个非 NIL 孩子，直接摘除。'}</div>`:''}
 <details id="rb-path-details"><summary>展开每条 NIL 路径，核对黑数守恒</summary><div class="rb-scroll"><table><thead><tr><th>根 → NIL 路径</th><th>实际黑数</th><th>虚拟 +1</th><th>有效黑数</th></tr></thead><tbody>${f.paths.map(p=>`<tr class="${p.debt?'rb-debt-row':''}"><td>${p.path.join(' → ')} <small>(${p.id})</small></td><td>${p.black}</td><td>${p.debt}</td><td>${p.effective}</td></tr>`).join('')}</tbody></table></div></details>
 <details id="rb-code-details"><summary>对照伪代码与当前分支</summary><p>rotate(parent, raise=child) 表示让指定孩子上升；根据孩子方位选择左右旋。NIL 始终视为黑。${mirrorMode?'当前为镜像模式：伪代码中的 successor 改为 predecessor。':''}</p><pre class="rb-code">${(ins?rbInsertCode:rbDeleteCode).map((line,i)=>{const highlights={I1:[3,4,5],I2:[6,7,8],I3:[9,10],'I-root':[11],D1:[6,7,8],D2:[9,10],D3:[11,12,13],D4:[14,15],'D-root':[16],'D-absorb':[16]};return `<span class="${!hidden&&highlights[f.caseId]?.includes(i)?'active':''}"><i>${i+1}</i>${esc(line)}</span>`}).join('')}</pre></details>
 <details id="rb-234"><summary>折叠为 2–3–4 树，看看颜色在编码什么</summary>${isComplete?`<p>把红孩子并入黑父，多键节点按中序排列；只在合法完成状态折叠。</p><div class="rb-scroll">${rb234SVG(f.root)}</div>`:'<p>这是修复中间态。请走到“操作完成”或初始状态，再查看合法的 2–3–4 树编码。</p>'}</details>`;
 for(const id of expanded)if(document.getElementById(id))document.getElementById(id).open=true;
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const el of document.querySelectorAll('#rb-current [data-rb-node]')){const p=oldPositions.get(el.dataset.rbNode);const body=el.querySelector('.rb-node-body');if(p?.fill&&body&&p.fill!==body.getAttribute('fill'))body.animate([{fill:p.fill},{fill:body.getAttribute('fill')}],{duration:420});if(p&&(p.x!==+el.dataset.x||p.y!==+el.dataset.y))el.animate([{transform:`translate(${p.x}px,${p.y}px)`},{transform:`translate(${el.dataset.x}px,${el.dataset.y}px)`}],{duration:420,easing:'ease-in-out'})}
 $('#rb-prev').disabled=pos===0;$('#rb-next').disabled=pos===frames.length-1;$('#rb-seek').value=pos;$('#rb-checkpoint').value=pos;
 document.querySelectorAll('[data-rb-answer]').forEach(b=>b.onclick=()=>{const correct=b.dataset.rbAnswer===f.caseId;feedback=correct?'判断正确。现在说出谁上升、谁变色，再走一步核对。':ins?'还不对。先检查父亲与叔叔；叔黑时再看 X、P、G 是折线还是直线。':'还不对。先检查兄弟颜色；兄弟黑时优先看远侄，再看近侄。';if(correct)revealed=true;paint()});if($('#rb-reveal'))$('#rb-reveal').onclick=()=>{revealed=true;feedback='已展开答案；下一次尝试先判断再看。';paint()};
 }
 function run(){stop();try{frames=rbLabTrace(parseRBKeys($('#rb-initial').value),parseRBOps($('#rb-ops').value),{predecessor:mirrorMode});pos=0;revealed=false;feedback='';$('#rb-error').textContent='';$('#rb-seek').max=frames.length-1;$('#rb-checkpoint').innerHTML=frames.map((f,i)=>`<option value="${i}">${i+1}. ${f.phase==='decision'&&quiz?'待预测的修复规则':esc(f.title)}</option>`).join('');paint()}catch(e){$('#rb-error').textContent=e.message+' 上次有效动画保留。'}}
 function loadPreset(id){mirrorMode=false;presetId=id;$('#rb-preset').value=id;const p=rbPresets.find(p=>p.id===id);$('#rb-initial').value=p.initial;$('#rb-ops').value=p.ops;$('#rb-preset-why').textContent=p.why;run()}
 $('#rb-preset').onchange=e=>loadPreset(e.target.value);$('#rb-run').onclick=()=>{$('#rb-preset-why').textContent='自定义案例：先选择路径与角色，再判断修复。';run()};$('#rb-initial').onkeydown=$('#rb-ops').onkeydown=e=>{if(e.key==='Enter')run()};$('#rb-prev').onclick=()=>setPosition(pos-1);$('#rb-next').onclick=()=>setPosition(pos+1);$('#rb-first').onclick=()=>setPosition(0);$('#rb-seek').oninput=e=>setPosition(+e.target.value);$('#rb-checkpoint').onchange=e=>setPosition(+e.target.value);
 $('#rb-play').onclick=()=>{if(timer){stop();return}if(quiz&&frames[pos].phase==='decision'&&!revealed){feedback='先完成当前判断，或展开答案后再播放。';paint();return}if(pos===frames.length-1)pos=0;$('#rb-play').textContent='Ⅱ 暂停';timer=setInterval(()=>{pos++;revealed=false;feedback='';paint();if(pos===frames.length-1||(quiz&&frames[pos].phase==='decision'))stop()},+$('#rb-speed').value)};$('#rb-speed').onchange=()=>{if(timer){stop();$('#rb-play').click()}};
 $('#rb-nil').onclick=()=>{showNil=!showNil;$('#rb-nil').setAttribute('aria-pressed',String(showNil));$('#rb-nil').textContent=showNil?'只显示相关 NIL':'显示全部 NIL';paint()};$('#rb-size').onclick=()=>{actual=!actual;$('#rb-size').setAttribute('aria-pressed',String(actual));$('#rb-size').textContent=actual?'适应画布':'原始字号';paint()};$('#rb-quiz').onclick=()=>{stop();quiz=!quiz;revealed=false;feedback='';$('#rb-quiz').setAttribute('aria-pressed',String(quiz));$('#rb-quiz').textContent=quiz?'关闭预测模式':'开启预测模式';$('#rb-checkpoint').innerHTML=frames.map((f,i)=>`<option value="${i}">${i+1}. ${quiz&&f.phase==='decision'?'待预测的修复规则':esc(f.title)}</option>`).join('');paint()};
 $('#rb-mirror').onclick=()=>{try{$('#rb-initial').value=parseRBKeys($('#rb-initial').value).map(x=>-x).join(' ');$('#rb-ops').value=parseRBOps($('#rb-ops').value).map(o=>`${o.type}:${-o.key}`).join(' ');mirrorMode=!mirrorMode;$('#rb-preset-why').textContent=mirrorMode?'镜像：键取反，双孩子删除由后继改取前驱，使整个执行过程左右对称；近/远始终相对 X 定义。':'已恢复原方向：双孩子删除取后继。';run()}catch(e){$('#rb-error').textContent=e.message}};
 $('#rb-export-guide').onclick=()=>save('ADS-redblack-memory-map.svg',rbGuideSVG(),'image/svg+xml');$('#rb-export-notes').onclick=()=>save('ADS-redblack-insert-delete.md',rbMemoryText(),'text/markdown;charset=utf-8');document.querySelectorAll('[data-rb-jump]').forEach(b=>b.onclick=()=>$('#'+b.dataset.rbJump).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));bindGuide();loadPreset(presetId);return stop;
}
